import sys
from collections import defaultdict

sys.setrecursionlimit(200000)

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    # Group edges by color
    color_edges = defaultdict(list)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        c = int(next(iterator))
        color_edges[c].append((u, v))

    # For each color, build DSU structure
    # We will store parent arrays for each color that appears
    # To save memory, we only store nodes that appear in that color's edges

    color_dsu = {}

    def get_root(parent, node):
        path = []
        while parent[node] != node:
            path.append(node)
            node = parent[node]
        for p in path:
            parent[p] = node
        return node

    def union(parent, rank, a, b):
        root_a = get_root(parent, a)
        root_b = get_root(parent, b)
        if root_a == root_b:
            return False

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        elif rank[root_a] == rank[root_b]:
            rank[root_a] += 1

        parent[root_b] = root_a
        return True

    # Process each color
    for c, edges in color_edges.items():
        # Collect all unique nodes for this color
        nodes = set()
        for u, v in edges:
            nodes.add(u)
            nodes.add(v)

        # Initialize DSU for these nodes
        parent = {node: node for node in nodes}
        rank = {node: 0 for node in nodes}

        for u, v in edges:
            union(parent, rank, u, v)

        # Compress paths for all nodes
        for node in nodes:
            get_root(parent, node)

        color_dsu[c] = parent

